    /**
     * @param Integer[] $arr
     * @return Integer
     */
    function numFactoredBinaryTrees($arr) {
        $mod = 1000000007;
        sort($arr);
        $n = count($arr);
        $dp = [];
        $total = 0;
        for ($i = 0; $i < $n; $i++) {
            $x = $arr[$i];
            $cnt = 1;
            for ($j = 0; $j < $i; $j++) {
                $a = $arr[$j];
                if ($x % $a == 0) {
                    $b = intdiv($x, $a);
                    if (isset($dp[$b])) {
                        $cnt = ($cnt + ($dp[$a] * $dp[$b]) % $mod) % $mod;
                    }
                }
            }
            $dp[$x] = $cnt;
            $total = ($total + $cnt) % $mod;
        }
        return $total;
    }
}
