    private $parent = [];
    private $sz = [];

    private function find($x) {
        $r = $x;
        while ($this->parent[$r] != $r) {
            $r = $this->parent[$r];
        }
        while ($this->parent[$x] != $r) {
            $nx = $this->parent[$x];
            $this->parent[$x] = $r;
            $x = $nx;
        }
        return $r;
    }

    private function union($a, $b) {
