            $was[$i] = $grid[$r][$c] == 1;
            $g[$r][$c] = 0;
        }
        $dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
        for ($i = 0; $i < $m; $i++) {
            for ($j = 0; $j < $n; $j++) {
                if ($g[$i][$j] == 1) {
                    if ($i == 0) $this->union($i * $n + $j, $top);
                    if ($i > 0 && $g[$i - 1][$j] == 1) $this->union($i * $n + $j, ($i - 1) * $n + $j);
