class CustomStack {
    private $stack = [];
    private $inc = [];
    private $size = 0;
    private $max;

    function __construct($maxSize) {
        $this->max = $maxSize;
    }

    function push($x) {
        if ($this->size < $this->max) {
            $this->stack[$this->size] = $x;
            $this->inc[$this->size] = 0;
            $this->size++;
        }
        return null;
    }

    function pop() {
        if ($this->size == 0) return -1;
        $i = $this->size - 1;
        $res = $this->stack[$i] + $this->inc[$i];
        if ($i > 0) {
            $this->inc[$i - 1] += $this->inc[$i];
        }
        $this->inc[$i] = 0;
        $this->size--;
        return $res;
    }

    function increment($k, $val) {
        $m = min($k, $this->size);
        if ($m > 0) {
            $this->inc[$m - 1] += $val;
