    /**
     * @param String $s
     * @return Integer[]
     */
    function diStringMatch($s) {
        $n = strlen($s);
        $lo = 0;
        $hi = $n;
        $res = [];
        for ($i = 0; $i < $n; $i++) {
            if ($s[$i] === 'I') {
                $res[] = $lo++;
            } else {
                $res[] = $hi--;
            }
        }
        $res[] = $lo;
        return $res;
    }
}
