    /**
     * @param Integer[][] $points
     * @return Integer
     */
    function maxPoints($points) {
        $n = count($points);
        if ($n <= 2) return $n;
        $best = 1;
        for ($i = 0; $i < $n; $i++) {
            $map = [];
            $local = 0;
            for ($j = $i + 1; $j < $n; $j++) {
                $dx = $points[$j][0] - $points[$i][0];
                $dy = $points[$j][1] - $points[$i][1];
                $a = abs($dx);
                $b = abs($dy);
                while ($b != 0) {
                    $t = $a % $b;
                    $a = $b;
                    $b = $t;
                }
                if ($a != 0) {
                    $dx = intdiv($dx, $a);
                    $dy = intdiv($dy, $a);
                }
                if ($dx < 0 || ($dx == 0 && $dy < 0)) {
                    $dx = -$dx;
                    $dy = -$dy;
                }
                $key = $dx . "," . $dy;
                if (!isset($map[$key])) $map[$key] = 0;
                $map[$key]++;
