class Solution {

    /**
     * @param Integer[] $nums
     * @return Integer
     */
    function maxEqualFreq($nums) {
        $cnt = [];
        $freq = array_fill(0, count($nums) + 2, 0);
        $maxF = 0;
        $ans = 0;
        $n = count($nums);
        for ($idx = 0; $idx < $n; $idx++) {
            $x = $nums[$idx];
            $i = $idx + 1;
            $c = isset($cnt[$x]) ? $cnt[$x] : 0;
            if ($c > 0) {
                $freq[$c]--;
            }
            $c++;
            $cnt[$x] = $c;
            $freq[$c]++;
            if ($c > $maxF) {
                $maxF = $c;
            }
            $ok = false;
            if ($maxF == 1) {
                $ok = true;
            } elseif ($freq[$maxF] * $maxF == $i - 1) {
                $ok = true;
            } elseif ($freq[$maxF] == 1 && $freq[$maxF - 1] * ($maxF - 1) + $maxF == $i) {
                $ok = true;
            }
            if ($ok) {
                $ans = $i;
            }
        }
        return $ans;
    }
