class Solution {

    /**
     * @param String $text
     * @param String $brokenLetters
     * @return Integer
     */
    function canBeTypedWords($text, $brokenLetters) {
        $broken = [];
        $n = strlen($brokenLetters);
        for ($i = 0; $i < $n; $i++) {
            $c = $brokenLetters[$i];
            if ($c !== ' ') {
                $broken[$c] = true;
            }
        }
        $count = 0;
        foreach (explode(' ', $text) as $w) {
            if ($w === '') continue;
            $ok = true;
            $l = strlen($w);
            for ($i = 0; $i < $l; $i++) {
                if (isset($broken[$w[$i]])) {
                    $ok = false;
                    break;
                }
            }
            if ($ok) $count++;
        }
        return $count;
    }
}
