inference_trace:
The solution uses a Fenwick tree (binary indexed tree) over the coordinate-compressed values, so each window costs O(log n) and the whole run is O(n log n).

1. Sort the unique values and map each value to a 1-based rank. The tree stores counts per rank, so duplicates are handled by the counts.
2. Insert the first `k` elements. For each window, find the k-th smallest element by descending the tree from the highest power of two at or below `m`, the number of unique values.
3. If `k` is odd, the median is the `(k+1)/2`-th smallest. If `k` is even, it is the average of the `k/2`-th and `(k/2+1)`-th smallest.
4. After recording a window's median, remove the outgoing element and add the incoming one.

```php
class Solution {

    /**
     * @param Integer[] $nums
     * @param Integer $k
     * @return Float[]
     */
    function medianSlidingWindow($nums, $k) {
        $n = count($nums);
        $vals = array_values(array_unique($nums));
        sort($vals);
        $m = count($vals);
        $rank = array_flip($vals); // value => 0-based index
        $tree = array_fill(0, $m + 1, 0);
        $top = 1;
        while ($top * 2 <= $m) $top *= 2;

        $update = function ($i, $d) use (&$tree, $m) {
            for (; $i <= $m; $i += $i & -$i) $tree[$i] += $d;
        };
        $kth = function ($kk) use (&$tree, $m, $top, $vals) {
            $pos = 0;
            for ($pw = $top; $pw > 0; $pw >>= 1) {
                $np = $pos + $pw;
                if ($np <= $m && $tree[$np] < $kk) {
                    $pos = $np;
                    $kk -= $tree[$np];
                }
            }
            return $vals[$pos];
        };

        for ($i = 0; $i < $k; $i++) {
            $update($rank[$nums[$i]] + 1, 1);
        }
        $res = [];
        for ($i = $k - 1; $i < $n; $i++) {
            if ($k % 2 == 1) {
                $res[] = (float)$kth(($k + 1) >> 1);
            } else {
                $a = $kth($k >> 1);
                $b = $kth(($k >> 1) + 1);
                $res[] = ($a + $b) / 2.0;
            }
            if ($i + 1 < $n) {
                $update($rank[$nums[$i - $k + 1]] + 1, -1);
                $update($rank[$nums[$i + 1]] + 1, 1);
            }
        }
        return $res;
    }
}
```

